examples.template:
VStack(alignment: .leading, spacing: 8) {
    MonarchFreshnessIndicator(
        updatedAt: lastSync,
        source: {{source}},
        details: [{{details.0}}],
        staleAfter: .seconds({{staleAfterSeconds}}),
        expiredAfter: .seconds({{expiredAfterSeconds}}),
        variant: {{variant|case}}
    ) {
        lastSync = .now
    }
    MonarchButton({{manageSource}}, variant: .ghost, size: .sm) {}
}

examples.code:
